// Phụ tùng có giá bán = 0đ — thường là lô mới nhập/import hàng loạt chưa kịp định giá.
// Báo giá 0đ cho khách khi lập lệnh sửa chữa là lỗi nghiêm trọng, không phải cosmetic. Báo
// NỘI BỘ cho quản lý xưởng, kèm 20 mã mẫu đầu tiên để bắt tay định giá ngay.
const d = $json;
const sample = d.sample || [];

const rows = sample.map(p => `<tr><td>${p.code}</td><td>${p.name}</td><td>${p.category}</td><td align="right">${p.stock}</td></tr>`).join('');

const html = `<h2>💲 ${d.count} phụ tùng chưa có giá bán</h2>`
  + `<p>Giá bán = 0đ sẽ bị báo giá sai cho khách khi lập lệnh sửa chữa. Danh sách dưới là ${sample.length} mã đầu tiên (sắp theo mã):</p>`
  + `<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse">`
  + `<tr><th>Mã</th><th>Tên phụ tùng</th><th>Nhóm</th><th>Tồn</th></tr>${rows}</table>`
  + `<p style="color:#888;font-size:12px">${d.company_name} — ${new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' })}</p>`;

return { json: {
  email_to: d.company_email || '',
  email_subject: `💲 ${d.count} phụ tùng còn thiếu giá bán`,
  email_html: html
} };
